-- MAFIVERA V1: building defense is stored in defense_points as the effective total.
-- This keeps partial attacks and building bonuses consistent.
create or replace function public.mafivera_build(p_zone_key text,p_building_type text) returns json language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid();p profiles;w world_territories;cost bigint;secs integer;bd integer;begin select * into p from profiles where id=uid for update;select * into w from world_territories where zone_key=p_zone_key for update;if not found or w.owner_id<>uid then raise exception 'territory_not_owned';end if;if w.building_type is not null then raise exception 'building_already_exists';end if;cost:=case p_building_type when 'warehouse' then 800 when 'money' then 250 when 'club' then 750 when 'lab' then 500 when 'market' then 900 when 'watch' then 600 when 'hideout' then 1000 when 'recruitment' then 1000 else 0 end;secs:=case p_building_type when 'warehouse' then 60 when 'money' then 45 when 'club' then 60 when 'lab' then 90 when 'market' then 90 when 'watch' then 75 when 'hideout' then 120 when 'recruitment' then 120 else 0 end;bd:=case p_building_type when 'watch' then 6 when 'hideout' then 19 else 0 end;if cost=0 then raise exception 'invalid_building';end if;if p.money<cost then raise exception 'insufficient_money';end if;update profiles set money=money-cost,updated_at=now() where id=uid;update world_territories set building_type=p_building_type,building_level=1,building_started_at=now(),building_finish_at=now()+make_interval(secs=>secs),defense_points=25+bd,building_defense=bd,updated_at=now() where zone_key=p_zone_key;return json_build_object('success',true);end;$$;
create or replace function public.mafivera_upgrade(p_zone_key text) returns json language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid();w world_territories;p profiles;cost bigint;secs integer;new_level integer;bd integer;begin select * into p from profiles where id=uid for update;select * into w from world_territories where zone_key=p_zone_key for update;if not found or w.owner_id<>uid then raise exception 'territory_not_owned';end if;if w.building_type is null then raise exception 'no_building';end if;if w.building_finish_at is not null and w.building_finish_at>now() then raise exception 'building_not_ready';end if;if w.building_level>=10 then raise exception 'max_level';end if;new_level:=w.building_level+1;cost:=case w.building_type when 'warehouse' then 600 when 'money' then 200 when 'club' then 500 when 'lab' then 400 when 'market' then 700 when 'watch' then 500 when 'hideout' then 800 when 'recruitment' then 800 else 0 end*new_level;secs:=30*new_level;bd:=case w.building_type when 'watch' then 6*new_level when 'hideout' then 19*new_level else 0 end;if p.money<cost then raise exception 'insufficient_money';end if;update profiles set money=money-cost,updated_at=now() where id=uid;update world_territories set building_level=new_level,building_started_at=now(),building_finish_at=now()+make_interval(secs=>secs),defense_points=25+bd,building_defense=bd,updated_at=now() where zone_key=p_zone_key;return json_build_object('success',true,'level',new_level);end;$$;
create or replace function public.mafivera_attack(p_zone_key text,p_count integer) returns json language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid();p profiles;t world_territories;z record;losses integer;remaining integer;damage integer;total_defense integer;begin select * into p from profiles where id=uid for update;select * into t from world_territories where zone_key=p_zone_key for update;if not found then raise exception 'territory_not_found';end if;if t.owner_id=uid then raise exception 'already_owned';end if;if p_count<1 then raise exception 'invalid_troops';end if;select * into z from mafivera_zone_center(p_zone_key);if not exists(select 1 from world_territories w cross join lateral mafivera_zone_center(w.zone_key) q where w.owner_id=uid and greatest(abs(q.r-z.r),abs(q.c-z.c))=1) then raise exception 'must_attack_adjacent';end if;if p.hitmen<p_count then raise exception 'not_enough_hitmen';end if;losses:=least(p_count,coalesce(t.garrison,0));remaining:=p_count-losses;total_defense:=greatest(1,t.defense_points);damage:=least(remaining,total_defense);update profiles set hitmen=hitmen-p_count,updated_at=now() where id=uid;if damage<total_defense then update world_territories set garrison=greatest(0,coalesce(garrison,0)-losses),defense_points=greatest(1,total_defense-damage),updated_at=now() where zone_key=p_zone_key;return json_build_object('success',false,'losses',p_count,'damage',damage,'defense_left',greatest(1,total_defense-damage));end if;update world_territories set owner_id=uid,defense_points=25,garrison=0,building_type=null,building_level=1,building_started_at=null,building_finish_at=null,building_defense=0,support_bonus=0,resources=mafivera_resources(p_zone_key),claimed_at=now(),updated_at=now() where zone_key=p_zone_key;update profiles set xp=xp+50,reputation=reputation+15,influence=influence+5,updated_at=now() where id=uid;return json_build_object('success',true,'captured',true,'building_destroyed',t.building_type is not null);end;$$;
grant execute on function public.mafivera_build(text,text) to authenticated;grant execute on function public.mafivera_upgrade(text) to authenticated;grant execute on function public.mafivera_attack(text,integer) to authenticated;
